package com.rulecraft.decisionops.workflow.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="decision_change_event")
public class DecisionChangeEvent {@Id private UUID id;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="change_request_id",nullable=false)private UUID requestId;@Column(name="client_request_id",nullable=false)private UUID clientRequestId;@Column(name="event_type",nullable=false,length=32)private String eventType;@Enumerated(EnumType.STRING)@Column(name="from_state",length=32)private ChangeRequestState fromState;@Enumerated(EnumType.STRING)@Column(name="to_state",nullable=false,length=32)private ChangeRequestState toState;@Column(length=2000)private String note;@Column(name="actor_id",nullable=false)private UUID actorId;@Column(name="actor_name",nullable=false,length=160)private String actorName;@Column(name="created_at",nullable=false)private Instant createdAt;protected DecisionChangeEvent(){}public DecisionChangeEvent(UUID tenantId,UUID requestId,UUID clientRequestId,String eventType,ChangeRequestState fromState,ChangeRequestState toState,String note,UUID actorId,String actorName,Instant now){id=UUID.randomUUID();this.tenantId=tenantId;this.requestId=requestId;this.clientRequestId=clientRequestId;this.eventType=eventType;this.fromState=fromState;this.toState=toState;this.note=note;this.actorId=actorId;this.actorName=actorName;createdAt=now;}public UUID getId(){return id;}public UUID getRequestId(){return requestId;}public UUID getClientRequestId(){return clientRequestId;}public String getEventType(){return eventType;}public ChangeRequestState getFromState(){return fromState;}public ChangeRequestState getToState(){return toState;}public String getNote(){return note;}public UUID getActorId(){return actorId;}public String getActorName(){return actorName;}public Instant getCreatedAt(){return createdAt;}}
